import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.DDY-poMm.js";const m=JSON.parse('{"title":"What is RWA-ECHO","description":"","frontmatter":{},"headers":[],"relativePath":"intro/what-is.md","filePath":"intro/what-is.md","lastUpdated":1790683574000}'),i={name:"intro/what-is.md"};function n(o,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="what-is-rwa-echo" tabindex="-1">What is RWA-ECHO <a class="header-anchor" href="#what-is-rwa-echo" aria-label="Permalink to &quot;What is RWA-ECHO&quot;">​</a></h1><p>RWA-ECHO is a <strong>centralized digital asset trading platform</strong> for teams who want to run their own trading business. Delivery includes the admin console, market maker portal, user PC site, user mobile H5 site and a <strong>native dual-platform app (Android / iOS)</strong>, covering the full journey from sign-up, KYC and deposits to trading, wealth products and withdrawals.</p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Self-operated digital asset exchanges</strong>: a complete user system, funds system, trading system and back-office controls</li><li><strong>Multi-asset trading</strong>: beyond digital assets, market data and trading for traditional instruments such as forex, commodities, stocks and indices</li><li><strong>Operations-heavy businesses</strong>: menus, featured coins, feature toggles, VIP tiers and many other operating elements can be adjusted in the admin console at any time, without asking engineers to change code</li></ul><h2 id="key-characteristics" tabindex="-1">Key characteristics <a class="header-anchor" href="#key-characteristics" aria-label="Permalink to &quot;Key characteristics&quot;">​</a></h2><h3 id="_1-configuration-driven-user-interface" tabindex="-1">1. Configuration-driven user interface <a class="header-anchor" href="#_1-configuration-driven-user-interface" aria-label="Permalink to &quot;1. Configuration-driven user interface&quot;">​</a></h3><p>The bottom menu, home shortcuts, featured coins, asset page tabs, side menu, VIP tier thresholds, feature toggles and more on the user side are <strong>all delivered from admin configuration</strong>. Changes take effect immediately on the user side — no new release needed.</p><p>See <a href="/CoinExchange/guide/site-config">Site Configuration</a>.</p><h3 id="_2-every-movement-of-funds-is-recorded" tabindex="-1">2. Every movement of funds is recorded <a class="header-anchor" href="#_2-every-movement-of-funds-is-recorded" aria-label="Permalink to &quot;2. Every movement of funds is recorded&quot;">​</a></h3><p>Each balance change comes with a ledger entry recording the balance before and after. Deposits, withdrawals, transfers, orders, settlements and manual adjustments are all processed as atomic transactions, preventing balance errors or double credits under high concurrency.</p><h3 id="_3-dual-deposit-channels-for-resilience" tabindex="-1">3. Dual deposit channels for resilience <a class="header-anchor" href="#_3-dual-deposit-channels-for-resilience" aria-label="Permalink to &quot;3. Dual deposit channels for resilience&quot;">​</a></h3><p>The platform supports two digital asset deposit channels in parallel, and operators can switch between them with one click in the admin console. If one channel fails, you can switch immediately without interrupting business. Each user has a stable, dedicated deposit address that does not need to be re-requested; deposits are credited automatically based on the amount actually received on-chain, with no manual review.</p><h3 id="_4-predictable-behavior-in-extreme-markets" tabindex="-1">4. Predictable behavior in extreme markets <a class="header-anchor" href="#_4-predictable-behavior-in-extreme-markets" aria-label="Permalink to &quot;4. Predictable behavior in extreme markets&quot;">​</a></h3><p>Contract liquidation and settlement include a quote-freshness check: if the market data feed is interrupted, stale quotes are detected and rejected, and the system pauses liquidation and conditional-order triggers for that instrument until data recovers, then re-evaluates at the real market price.</p><blockquote><p><strong>The principle is clear: a delayed liquidation is acceptable; a wrong liquidation is not.</strong></p></blockquote><p>A position is settled exactly once. If market data is temporarily missing when an option-style order expires, the system uses a &quot;bounded wait + timeout fallback&quot; strategy: on timeout the order is cancelled and the principal is refunded to its source, with a full record. There are no &quot;charged but neither settled nor refunded&quot; hanging orders.</p><h2 id="what-it-is-not-for" tabindex="-1">What it is not for <a class="header-anchor" href="#what-it-is-not-for" aria-label="Permalink to &quot;What it is not for&quot;">​</a></h2><ul><li><strong>Decentralized exchange (DEX) use cases</strong>: this is a centralized matching and bookkeeping model; the blockchain is used only for deposits and withdrawals</li><li><strong>Use cases requiring real exchange order-book depth</strong>: execution prices come from the platform&#39;s market data cache</li></ul><h2 id="request-a-demo" tabindex="-1">Request a demo <a class="header-anchor" href="#request-a-demo" aria-label="Permalink to &quot;Request a demo&quot;">​</a></h2><p>The demo site address and trial accounts are not published in these docs; see <a href="/CoinExchange/contact/">Contact</a> to request access.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>A quick look at what the system can do → <a href="/CoinExchange/intro/features">Features</a></li><li>What the system is made of and who uses each part → <a href="/CoinExchange/intro/components">System Components</a></li><li>Getting started as an operator → <a href="/CoinExchange/guide/admin-login">Admin Login &amp; Permissions</a></li><li>Want to try it yourself → request a demo account via <a href="/CoinExchange/contact/">Contact</a></li></ul>',22)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
